1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The duplicate block of the create-owner pipeline: rejects the request with a 409 (via
11	 * {@code DuplicateIdentityExceptionHandler}) on an <b>identity duplicate</b> — an exact match on the
12	 * whole {@link IdentityKey} (the SHA-256 of {@code telephone|email|soundex(lastName)}) — because that
13	 * is the same person. This single identity key is now the only duplicate rule: there is no separate
14	 * household-duplicate 409 keyed off the computed {@link HouseholdKey#householdId}.
15	 *
16	 * <p>Sharing a last name and postcode is <em>not</em> in itself a duplicate: two owners with the same
17	 * last name and postcode but different telephones have different identity keys and are both allowed —
18	 * the second is created and flagged as a soft match by {@link AssignOwnerPossibleDuplicate}. A new
19	 * member's membershipLevel is then capped relative to the existing members by {@link OwnerHousehold};
20	 * it is no longer necessary to declare {@code sharesHousehold}.
21	 *
22	 * <p>Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail}, so the candidate's
23	 * telephone and email are already normalized, and after {@link RequireEmailNotDisposable} so the
24	 * email-domain blocklist is applied first. The new owner is not persisted yet, so every match found is
25	 * another owner.
26	 */
27	public class RequireUniqueIdentity {
28	
29	    public void service(@Val OwnerFieldsDto owner, OwnerRepository ownerRepository)
30	            throws DuplicateIdentityException {
31	        String candidate = IdentityKey.of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (!DuplicateCandidates.isCandidate(existing)) {
34	                continue; // a soft-deleted owner no longer blocks a duplicate or identity match
35	            }
36	            if (candidate.equals(IdentityKey.ofOwner(existing))) {
37	                throw new DuplicateIdentityException(candidate);
38	            }
